steps.kql:
// PURPOSE: scope the blast radius — the set of devices and the initiating
// processes reaching the domain names the affected hosts and the malware.
DeviceNetworkEvents
| where TimeGenerated > ago(14d)
| where RemoteUrl has "{{domain}}"
| summarize Connections = count(),
            Devices     = dcount(DeviceName),
            DeviceList  = make_set(DeviceName, 50),
            Processes   = make_set(tostring(column_ifexists("InitiatingProcessFileName", "")), 25),
            RemoteIPs   = make_set(tostring(column_ifexists("RemoteIP", "")), 25),
            FirstSeen   = min(TimeGenerated),
            LastSeen    = max(TimeGenerated)
    by RemoteUrl
| order by Connections desc
//
// Look for: a Processes entry that is NOT a browser — powershell, rundll32,
//   an unsigned binary, or a random name reaching the domain = C2, not browsing.
// Benign twin: chrome/msedge/firefox reaching a CDN or a legitimate SaaS
//   subdomain is normal traffic.
// Next: go to step 2 to test whether the timing looks like beaconing.

// PURPOSE: separate human browsing (bursty, irregular) from C2 beaconing
// (regular interval, low jitter). Uses the mean/stdev of inter-connection gaps.
DeviceNetworkEvents
| where TimeGenerated > ago(14d)
| where RemoteUrl has "{{domain}}"
| sort by DeviceName asc, TimeGenerated asc
| extend PrevTime = prev(TimeGenerated), PrevDevice = prev(DeviceName)
| where DeviceName == PrevDevice
| extend GapSeconds = datetime_diff('second', TimeGenerated, PrevTime)
| summarize Beacons     = count(),
            MeanGapSec  = avg(GapSeconds),
            StdevGapSec = stdev(GapSeconds),
            Process     = make_set(tostring(column_ifexists("InitiatingProcessFileName", "")), 10)
    by DeviceName
| where Beacons >= 10
| extend JitterRatio = iff(MeanGapSec > 0, StdevGapSec / MeanGapSec, 999.0)
| where JitterRatio < 0.3
| order by JitterRatio asc
//
// Look for: a LOW JitterRatio (< 0.3) with a consistent MeanGapSec — regular
//   call-outs at a fixed interval are the beaconing signature.
// Benign twin: software update checks and telemetry also beacon regularly;
//   the Process set tells them apart (a signed updater vs rundll32/powershell).
// Next: a low-jitter beacon from a non-browser process is C2 — isolate the
//   host, capture the process, and pivot on its file hash (file-hash playbook).

// PURPOSE: prevalence is triage. One device is contained; fifty is an
// incident. Paths + the process that wrote it hint at delivery.
DeviceFileEvents
| where TimeGenerated > ago(30d)
| where SHA256 == "{{sha256}}"
| summarize Devices    = dcount(DeviceName),
            DeviceList = make_set(DeviceName, 50),
            Names      = make_set(FileName, 20),
            Paths      = make_set(FolderPath, 20),
            WrittenBy  = make_set(tostring(column_ifexists("InitiatingProcessFileName", "")), 20),
            FirstSeen  = min(TimeGenerated),
            LastSeen   = max(TimeGenerated)
//
// Look for: many Devices = active spread; a FolderPath under Downloads/Temp/
//   AppData + a browser or Office WrittenBy = a phishing/drive-by delivery.
// Benign twin: a signed tool in Program Files on one admin box, written by an
//   installer, is usually legitimate — confirm the signer separately.
// Next: go to step 2 — landing is not execution. A dormant file is lower
//   priority than one that ran.

// PURPOSE: execution changes everything — now you have command lines, the
// parent process, and the account it ran as.
DeviceProcessEvents
| where TimeGenerated > ago(30d)
| where SHA256 == "{{sha256}}"
| project TimeGenerated, DeviceName,
          Account = strcat(tostring(column_ifexists("AccountDomain", "")), "\\",
                           tostring(column_ifexists("AccountName", ""))),
          FileName,
          CommandLine  = tostring(column_ifexists("ProcessCommandLine", "")),
          ParentProc   = tostring(column_ifexists("InitiatingProcessFileName", "")),
          ParentCmd    = tostring(column_ifexists("InitiatingProcessCommandLine", ""))
| order by TimeGenerated asc
//
// Look for: a ParentProc of winword/excel/outlook/powershell/wscript, or a
//   CommandLine with encoded/download flags — that is the execution chain.
// Benign twin: launched by explorer.exe by a real user with a normal command
//   line can still be legitimate software; corroborate with the signer/prevalence.
// Next: if it ran, pivot on ParentProc/CommandLine for the wider chain, and
//   check step 3 for stealthy module loads on the same hash.

// PURPOSE: catches the DLL-side-loading case where the malicious hash never
// appears as a process — it is loaded by a trusted, signed EXE.
DeviceImageLoadEvents
| where TimeGenerated > ago(30d)
| where SHA256 == "{{sha256}}"
| project TimeGenerated, DeviceName,
          Module   = FileName,
          Path     = FolderPath,
          LoadedBy = tostring(column_ifexists("InitiatingProcessFileName", "")),
          LoadedByPath = tostring(column_ifexists("InitiatingProcessFolderPath", ""))
| order by TimeGenerated asc
//
// Look for: a LoadedBy that is a legitimate signed binary loading this module
//   from a non-standard Path (Downloads/Temp/a user profile) = classic
//   DLL search-order hijack / side-loading.
// Benign twin: a module loaded from System32/Program Files by its own product
//   is normal.
// Next: a hit means the trusted LoadedBy process is now suspect — pivot the
//   investigation to that process and its host.

// PURPOSE: confirm the spray SHAPE — one source hitting many accounts with
// a low per-account attempt rate, and whether any attempt succeeded.
SigninLogs
| where TimeGenerated > ago(7d)
| where IPAddress == "{{ip}}"
| summarize Attempts  = count(),
            Accounts  = dcount(UserPrincipalName),
            Failures  = countif(ResultType != "0"),
            Successes = countif(ResultType == "0")
    by bin(TimeGenerated, 1h)
| order by Accounts desc
//
// Look for: a burst of many DISTINCT accounts per hour with mostly failures
//   and a handful of successes — that is a spray that landed.
// Benign twin: one account failing repeatedly from one IP is a stuck client
//   or a forgotten password, not a spray. Accounts stays ~1.
// Next: go to step 2 to list the accounts that succeeded.

// PURPOSE: name the accounts. A spray with >=1 AnySuccess is a confirmed
// compromise for that account — carry it into steps 3-5.
SigninLogs
| where TimeGenerated > ago(7d)
| where IPAddress == "{{ip}}"
| summarize AttemptsPerAccount = count(),
            AnySuccess = countif(ResultType == "0")
    by UserPrincipalName
| order by AnySuccess desc, AttemptsPerAccount asc
//
// Look for: rows with AnySuccess > 0 and a LOW AttemptsPerAccount — the
//   spray guessed the password on the first few tries. Those are compromised.
// Benign twin: AnySuccess = 0 across all accounts = the spray failed; monitor
//   but no account action needed.
// Next: take a UserPrincipalName with AnySuccess > 0 into {{upn}} for steps
//   3-5 (persistence). If none succeeded, close as a blocked spray.

// PURPOSE: the single most common post-compromise action on a mailbox.
// NOTE: Exchange operations live in OfficeActivity, NOT AuditLogs.
OfficeActivity
| where TimeGenerated > ago(7d)
| where OfficeWorkload =~ "Exchange"
| where Operation in~ ("New-InboxRule", "Set-InboxRule", "UpdateInboxRules",
                       "Set-Mailbox", "Set-TransportRule", "New-TransportRule")
| extend TargetUser = tostring(column_ifexists("UserId", ""))
| where TargetUser =~ "{{upn}}"
    or tostring(column_ifexists("MailboxOwnerUPN", "")) =~ "{{upn}}"
| project TimeGenerated, Operation, TargetUser,
          ClientIP  = tostring(column_ifexists("ClientIP", "")),
          ResultStatus = tostring(column_ifexists("ResultStatus", "")),
          RuleParams = tostring(column_ifexists("Parameters", ""))
| order by TimeGenerated desc
//
// Look for: a rule whose parameters contain ForwardTo / RedirectTo /
//   DeleteMessage — especially forwarding to an EXTERNAL domain, or one
//   filing security/IT mail into RSS/Archive/Deleted to hide the alert.
// Also: compare ClientIP here to the spray IP from step 1 — same IP is
//   confirmation, not coincidence.
// Next: any hit = confirmed compromise. Preserve + remove the rule, revoke
//   sessions, reset the credential. Continue to steps 4-5 (more anchors).

// PURPOSE: an illicit consent grant survives a password reset and MFA
// re-registration. Reset alone does not evict a consented application.
AuditLogs
| where TimeGenerated > ago(7d)
| where OperationName has_any ("Consent to application",
                               "Add OAuth2PermissionGrant",
                               "Add app role assignment grant to user",
                               "Add delegated permission grant",
                               "Add service principal")
| extend Actor   = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.userPrincipalName)
| extend ActorIp = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.ipAddress)
| where Actor =~ "{{upn}}"
| project TimeGenerated, OperationName, Actor, ActorIp,
          Result = tostring(column_ifexists("Result", "")),
          Target = tostring(column_ifexists("TargetResources", dynamic(null)))
| order by TimeGenerated desc
//
// Look for: a consent in the same window as the spray success, to an app you
//   do not recognise or one requesting Mail.Read / offline_access / Files.Read.All.
// Benign twin: users legitimately consent to SaaS. Check the ActorIp against
//   the spray IP before calling it malicious.
// Next: a hit means reset alone is insufficient — revoke the grant / service
//   principal and audit what it accessed.

// PURPOSE: registering their own authenticator keeps access through your
// password reset. Check this BEFORE you reset.
AuditLogs
| where TimeGenerated > ago(7d)
| where OperationName has_any ("Add security info", "User registered security info",
                               "User changed default security info",
                               "Add registered device", "Register device",
                               "Add device", "Update device",
                               "Admin registered security info",
                               "User deleted security info")
| extend Actor     = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.userPrincipalName)
| extend ActorIp   = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.ipAddress)
| extend TargetUpn = tostring(column_ifexists("TargetResources", dynamic(null)))
| where Actor =~ "{{upn}}" or TargetUpn has "{{upn}}"
| project TimeGenerated, OperationName, Actor, ActorIp,
          Result = tostring(column_ifexists("Result", "")),
          TargetUpn
| order by TimeGenerated desc
//
// Look for: a security-info / device registration within minutes of the
//   spray success, from the same ActorIp — the attacker provisioning their
//   own MFA so the account survives your reset.
// Benign twin: a genuine new-phone enrolment — corroborate with the user.
// Next: remove the attacker-registered method and revoke refresh tokens
//   FIRST, then reset the credential. Resetting first hands them a fresh session.

// PURPOSE: separate "never seen before" from "unusual but known". Scores
// this account's last 24h against its own 14-day baseline; a managed
// device reduces the score because it is evidence of legitimacy.
let lookback = 14d;
let recent   = 1d;
let baseline =
    SigninLogs
    | where TimeGenerated between (ago(lookback) .. ago(recent))
    | where UserPrincipalName =~ "{{upn}}"
    | where ResultType == "0"
    | extend Country = tostring(column_ifexists("LocationDetails", dynamic(null)).countryOrRegion)
    | extend OS      = tostring(column_ifexists("DeviceDetail", dynamic(null)).operatingSystem)
    | extend ASN     = tostring(column_ifexists("AutonomousSystemNumber", ""))
    | summarize KnownCountries = make_set(Country, 50),
                KnownASNs      = make_set(ASN, 50),
                KnownOS        = make_set(OS, 25)
        by UserPrincipalName;
SigninLogs
| where TimeGenerated > ago(recent)
| where UserPrincipalName =~ "{{upn}}"
| where ResultType == "0"
| extend Country = tostring(column_ifexists("LocationDetails", dynamic(null)).countryOrRegion)
| extend OS      = tostring(column_ifexists("DeviceDetail", dynamic(null)).operatingSystem)
| extend ASN     = tostring(column_ifexists("AutonomousSystemNumber", ""))
| extend Managed = tostring(column_ifexists("DeviceDetail", dynamic(null)).isManaged)
| join kind=inner baseline on UserPrincipalName
| extend Score =
      toint(not(set_has_element(KnownCountries, Country))) * 3
    + toint(not(set_has_element(KnownASNs, ASN)))          * 3
    + toint(not(set_has_element(KnownOS, OS)))             * 1
    - toint(Managed =~ "true")                             * 2
| where Score >= 4
| project TimeGenerated, UserPrincipalName, IPAddress, Country, ASN, OS, Managed, Score, AppDisplayName
| order by Score desc
//
// Look for: Score >= 4 with Managed != true — new country AND new ASN on
//   an unmanaged device is the strongest single signal short of a token
//   replay hit in step 6.
// Benign twin: a brand-new account, or a user with < 14 days of history,
//   has an empty baseline and will score high on everything. Check
//   FirstSeen before believing it.
// Next: regardless of score, continue to step 3 — persistence is
//   established in minutes, so absence of novelty does not clear the account.

// PURPOSE: the single most common post-compromise action on a mailbox.
// NOTE: Exchange operations live in OfficeActivity, NOT AuditLogs.
OfficeActivity
| where TimeGenerated > ago(7d)
| where OfficeWorkload =~ "Exchange"
| where Operation in~ ("New-InboxRule", "Set-InboxRule", "UpdateInboxRules",
                       "Set-Mailbox", "Set-TransportRule", "New-TransportRule")
| extend TargetUser = tostring(column_ifexists("UserId", ""))
| where TargetUser =~ "{{upn}}"
    or tostring(column_ifexists("MailboxOwnerUPN", "")) =~ "{{upn}}"
| extend RuleParams = tostring(column_ifexists("Parameters", ""))
| project TimeGenerated, Operation, TargetUser,
          ClientIP  = tostring(column_ifexists("ClientIP", "")),
          ResultStatus = tostring(column_ifexists("ResultStatus", "")),
          RuleParams
| order by TimeGenerated desc
//
// Look for: a rule whose parameters contain ForwardTo, ForwardAsAttachmentTo,
//   RedirectTo, or DeleteMessage — especially forwarding to an EXTERNAL
//   domain, or a rule that files security/IT mail into RSS/Archive/Deleted
//   (the attacker hiding the "unusual sign-in" notice from the user).
// Also: compare ClientIP here to the IP from step 1. A rule created from
//   the same IP is confirmation, not coincidence.
// Next: any hit here = confirmed compromise. Preserve the rule (screenshot
//   + export), then remove it, revoke sessions, and reset credentials.
//   Continue to steps 4-6 — attackers commonly set more than one anchor.

// PURPOSE: an illicit consent grant survives a password reset and MFA
// re-registration. If you only reset the password, you have not evicted them.
AuditLogs
| where TimeGenerated > ago(7d)
| where OperationName has_any ("Consent to application",
                               "Add OAuth2PermissionGrant",
                               "Add app role assignment grant to user",
                               "Add delegated permission grant",
                               "Add service principal")
| extend Actor = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.userPrincipalName)
| extend ActorIp = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.ipAddress)
| where Actor =~ "{{upn}}"
| extend Target = tostring(column_ifexists("TargetResources", dynamic(null)))
| project TimeGenerated, OperationName, Actor, ActorIp,
          Result = tostring(column_ifexists("Result", "")),
          Target
| order by TimeGenerated desc
//
// Look for: any consent granted in the same window as the step-1 sign-in,
//   particularly to an application you do not recognise, or one requesting
//   Mail.Read / Mail.ReadWrite / offline_access / Files.Read.All.
// Benign twin: users legitimately consent to SaaS tools. Check whether the
//   ActorIp matches the suspicious IP from step 1 before calling it malicious.
// Next: a hit means credential reset alone is insufficient — revoke the
//   service principal / OAuth grant and audit what it accessed.

// PURPOSE: registering their own authenticator or device is how an attacker
// keeps access through your password reset. Check this BEFORE you reset.
AuditLogs
| where TimeGenerated > ago(7d)
| where OperationName has_any ("Add security info", "User registered security info",
                               "User changed default security info",
                               "Add registered device", "Register device",
                               "Add device", "Update device",
                               "Admin registered security info",
                               "User deleted security info")
| extend Actor   = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.userPrincipalName)
| extend ActorIp = tostring(column_ifexists("InitiatedBy", dynamic(null)).user.ipAddress)
| extend TargetUpn = tostring(column_ifexists("TargetResources", dynamic(null)))
| where Actor =~ "{{upn}}" or TargetUpn has "{{upn}}"
| project TimeGenerated, OperationName, Actor, ActorIp,
          Result = tostring(column_ifexists("Result", "")),
          TargetUpn
| order by TimeGenerated desc
//
// Look for: a security-info / device registration within minutes of the
//   step-1 sign-in, from the same ActorIp. That is the attacker provisioning
//   their own MFA so the account survives your reset.
// Benign twin: a genuine new-phone enrolment — corroborate with the user.
// Next: a hit changes remediation ORDER — remove the attacker-registered
//   method and revoke refresh tokens FIRST, then reset the credential.
//   Resetting first simply hands them a fresh session.

// PURPOSE: covers the case where nothing above fires because the credential
// was never stolen — a session token was. A single session id appearing from
// two networks minutes apart is theft, not travel.
SigninLogs
| where TimeGenerated > ago(7d)
| where UserPrincipalName =~ "{{upn}}"
| where ResultType == "0"
| extend SessionKey = coalesce(tostring(column_ifexists("SessionId", "")),
                               tostring(column_ifexists("UniqueTokenIdentifier", "")))
| where isnotempty(SessionKey)
| extend Country = tostring(column_ifexists("LocationDetails", dynamic(null)).countryOrRegion)
| extend ASN     = tostring(column_ifexists("AutonomousSystemNumber", ""))
| summarize IPs        = dcount(IPAddress),
            IPList     = make_set(IPAddress, 25),
            ASNs       = make_set(ASN, 25),
            Countries  = make_set(Country, 25),
            Apps       = make_set(AppDisplayName, 25),
            FirstSeen  = min(TimeGenerated),
            LastSeen   = max(TimeGenerated)
    by SessionKey, UserPrincipalName
| where IPs > 1
| extend SpanMinutes = datetime_diff('minute', LastSeen, FirstSeen)
| project UserPrincipalName, SessionKey, IPs, SpanMinutes, IPList, ASNs, Countries, Apps, FirstSeen, LastSeen
| order by IPs desc, SpanMinutes asc
//
// Look for: IPs > 1 with a SHORT SpanMinutes and different ASNs/Countries —
//   the same token used from two networks at once. Include the step-1 IP in
//   IPList and it is confirmed replay.
// Benign twin: a long SpanMinutes across one ASN is usually a roaming client
//   or a proxy hop, not theft. Mobile carriers legitimately change egress IP.
// Next: replay means the credential reset is NOT the fix — revoke refresh
//   tokens / sign-in sessions for the account, then review what the session
//   accessed (steps 3-5 outputs) before closing.
